import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"AI in JEO","description":"","frontmatter":{},"headers":[],"relativePath":"ai-in-jeo/index.md","filePath":"ai-in-jeo.md"}'),n={name:"ai-in-jeo/index.md"};function s(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-in-jeo" tabindex="-1">AI in JEO <a class="header-anchor" href="#ai-in-jeo" aria-label="Permalink to &quot;AI in JEO&quot;">​</a></h1><p>JEO includes built-in AI capabilities for georeferencing posts, generating maps, and suggesting editorial content. This page explains the underlying concepts so you can understand what happens behind the scenes and how to get the best results.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>JEO&#39;s AI features are powered by a configurable external AI provider. The plugin never runs its own AI model — instead, it sends requests to the provider you choose (such as OpenAI, Google Gemini, or a local Ollama instance) and processes the results.</p><p>All AI features are <strong>optional</strong>. They activate only after you configure a provider in <strong>Jeo → AI</strong> (see <a href="/docs/ai-settings/">AI Settings</a>).</p><p>The key idea is that each AI feature is a specialized <strong>agent</strong> — an AI assistant with a specific role, a set of <strong>tools</strong> it can use, and access to your site&#39;s content through a <strong>knowledge base</strong>.</p><h2 id="ai-providers" tabindex="-1">AI providers <a class="header-anchor" href="#ai-providers" aria-label="Permalink to &quot;AI providers&quot;">​</a></h2><p>JEO supports multiple AI providers through <a href="https://docs.neuron-ai.dev/providers/ai-provider" target="_blank" rel="noreferrer">NeuronAI</a>. Most providers run in the cloud and require an API key, while others (such as Ollama) run locally on your own server — meaning no data ever leaves your server.</p><p>You select a provider and model in <strong>Jeo → AI → Provider</strong>. The same provider is used across all AI features. The list of available providers is shown on the settings page and may grow over time as NeuronAI adds new integrations.</p><h2 id="knowledge-base-rag" tabindex="-1">Knowledge Base (RAG) <a class="header-anchor" href="#knowledge-base-rag" aria-label="Permalink to &quot;Knowledge Base (RAG)&quot;">​</a></h2><p><strong>RAG</strong> stands for <em>Retrieval-Augmented Generation</em>. It is a technique that lets the AI search your own content before answering, so its responses are grounded in your site&#39;s data rather than generic knowledge.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>JEO maintains <strong>two separate knowledge bases</strong> (called <em>vector stores</em>):</p><table tabindex="0"><thead><tr><th>Knowledge base</th><th>Content</th><th>Used by</th></tr></thead><tbody><tr><td><strong>Posts</strong> (<code>jeo_knowledge</code>)</td><td>Your published posts — titles and body text</td><td><a href="/docs/ai-context-assistant/">Context Assistant</a></td></tr><tr><td><strong>Layers</strong> (<code>jeo_layers_knowledge</code>)</td><td>Your map layers — titles, types, legends, and descriptions</td><td><a href="/docs/minimap/">Minimap</a></td></tr></tbody></table><p>Each item is converted into a numerical representation (an <em>embedding</em>) and stored in a local file-based index. When an AI feature needs context, it:</p><ol><li>Converts the query into an embedding using the same model.</li><li>Searches the index for the most similar entries.</li><li>Passes the matching content to the AI along with the original request.</li></ol><p>This means the AI can reference your actual articles and layers when generating results.</p><h3 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h3><p>Content is added to the knowledge base through <em>indexing</em>. You control this in <strong>Jeo → AI → Knowledge Base</strong>:</p><ul><li><strong>Auto-indexing</strong> runs in the background via WordPress cron and picks up new or updated posts and layers.</li><li><strong>Manual indexing</strong> lets you trigger a full or partial re-index from the settings page.</li><li><strong>WP-CLI</strong> is also available for large-scale indexing: <code>wp jeo ai vectorize --store=posts --batch_size=20</code>.</li></ul><h3 id="embedding-models" tabindex="-1">Embedding models <a class="header-anchor" href="#embedding-models" aria-label="Permalink to &quot;Embedding models&quot;">​</a></h3><p>Embeddings are generated by a separate model from your AI provider. You configure the embedding model in the Knowledge Base tab. Common choices include <code>text-embedding-3-small</code> (OpenAI), <code>text-embedding-004</code> (Gemini), or <code>nomic-embed-text</code> (Ollama).</p><p>Once a knowledge base is created with a specific embedding model, that model is <em>locked</em> — changing it requires clearing and rebuilding the store, because embeddings from different models are not comparable.</p><h3 id="search-results-topk" tabindex="-1">Search results (topK) <a class="header-anchor" href="#search-results-topk" aria-label="Permalink to &quot;Search results (topK)&quot;">​</a></h3><p>The <strong>topK</strong> setting (in Knowledge Base tab, range 1–50, default 10) controls how many documents are returned per search. Higher values give the AI more context but increase token usage. For most use cases, 10 is a good default.</p><h2 id="how-each-feature-uses-rag" tabindex="-1">How each feature uses RAG <a class="header-anchor" href="#how-each-feature-uses-rag" aria-label="Permalink to &quot;How each feature uses RAG&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Uses RAG?</th><th>Knowledge base</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/docs/ai-georeferencing/">AI Georeferencing</a></td><td>Optional</td><td>—</td><td>Can include taxonomy context; does not use the vector store directly</td></tr><tr><td><a href="/docs/minimap/">Minimap</a></td><td>Yes</td><td>Layers (<code>jeo_layers_knowledge</code>)</td><td>Searches for relevant map layers to include in the generated map</td></tr><tr><td><a href="/docs/ai-context-assistant/">Context Assistant</a></td><td>Yes</td><td>Posts (<code>jeo_knowledge</code>)</td><td>Finds related articles to reference in suggestions</td></tr><tr><td><a href="/docs/ai-bulk-geolocation/">AI Bulk Geolocation</a></td><td>No</td><td>—</td><td>Processes posts individually without RAG</td></tr><tr><td>Minilayer</td><td>No</td><td>—</td><td>Uses MCP instead (see below)</td></tr></tbody></table><h2 id="structured-output" tabindex="-1">Structured output <a class="header-anchor" href="#structured-output" aria-label="Permalink to &quot;Structured output&quot;">​</a></h2><p>When the AI returns data — such as geolocation points or map configurations — JEO needs to parse it reliably. <strong>Structured output</strong> is a mechanism where the AI provider enforces a specific JSON schema at the API level, guaranteeing the response matches the expected format.</p><p>This is enabled by default and used by:</p><ul><li><strong>Georeferencing</strong> — returns locations with name, coordinates, confidence score, and primary/secondary classification.</li><li><strong>Minimap</strong> — returns the complete map configuration (layers, center, zoom, pins).</li><li><strong>Context Assistant</strong> — returns paragraphs and references.</li></ul><p>If your provider does not support structured output, or if it fails for any reason, JEO automatically falls back to a free-text mode that extracts the data using pattern matching. You don&#39;t need to configure anything — the fallback is transparent.</p><h2 id="agents-and-tools" tabindex="-1">Agents and tools <a class="header-anchor" href="#agents-and-tools" aria-label="Permalink to &quot;Agents and tools&quot;">​</a></h2><p>Each AI feature is built around an <strong>agent</strong> — an AI assistant configured for a specific task. Agents are given a system prompt (instructions), a set of <strong>tools</strong> they can call, and optionally access to <strong>sub-agents</strong> for delegated work.</p><h3 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;The tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th><th>Used by</th></tr></thead><tbody><tr><td><code>search_layers</code></td><td>Searches the layer knowledge base for relevant layers</td><td>Minimap</td></tr><tr><td><code>geocode</code></td><td>Converts a location name into latitude/longitude coordinates</td><td>Minimap</td></tr><tr><td><code>retrieve_knowledge</code></td><td>Searches the post knowledge base for related articles</td><td>Context Assistant</td></tr><tr><td><code>get_post_content</code></td><td>Retrieves a post&#39;s title, content, categories, tags, and geolocations</td><td>Minimap, Context Assistant</td></tr><tr><td><code>generate_layer</code></td><td>Creates a new Mapbox style and layer CPT from a description</td><td>Minimap (requires Mapbox key)</td></tr></tbody></table><p>When you ask the Minimap to &quot;show deforestation data in the Amazon,&quot; the agent might:</p><ol><li>Use <code>get_post_content</code> to understand the current article.</li><li>Use <code>search_layers</code> to find layers about deforestation.</li><li>Use <code>geocode</code> to locate the Amazon region.</li><li>Return a complete map configuration.</li></ol><h3 id="sub-agents" tabindex="-1">Sub-agents <a class="header-anchor" href="#sub-agents" aria-label="Permalink to &quot;Sub-agents&quot;">​</a></h3><p>Some agents delegate work to specialized sub-agents. Both Minimap and Context Assistant use a <strong>post analyzer</strong> sub-agent that reads the post content and extracts topics, locations, tone, and suggested search queries. This analysis guides the main agent&#39;s decisions.</p><h2 id="conversation-memory" tabindex="-1">Conversation memory <a class="header-anchor" href="#conversation-memory" aria-label="Permalink to &quot;Conversation memory&quot;">​</a></h2><p>AI features that support chat (Minimap, Context Assistant, and Georeferencing) maintain <strong>conversation history</strong> per post. This means:</p><ul><li>You can refine results through back-and-forth chat without repeating context.</li><li>Conversations persist across page reloads — closing the editor and returning later resumes where you left off.</li><li>Each post has its own independent conversation.</li></ul><h3 id="learning-and-user-memory" tabindex="-1">Learning and user memory <a class="header-anchor" href="#learning-and-user-memory" aria-label="Permalink to &quot;Learning and user memory&quot;">​</a></h3><p>The Minimap and Context Assistant agents can <strong>learn</strong> from interactions. Over time, they accumulate knowledge about patterns and preferences. They also store per-user memory (e.g., preferred writing style), so suggestions become more personalized the more you use them.</p><h2 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h2><p><strong>MCP</strong> is a protocol that connects AI agents to external services. In JEO, it is used exclusively by the <strong>Minilayer</strong> feature to communicate with the Mapbox MCP DevKit — an external service that generates Mapbox map styles.</p><p>When you ask the AI to create a custom layer (e.g., &quot;generate a deforestation heatmap for the Amazon&quot;), the Minilayer agent:</p><ol><li>Connects to the Mapbox MCP server using your Mapbox API key.</li><li>Uses Mapbox&#39;s tools to build, validate, and preview the style.</li><li>Creates a new layer post in WordPress with the generated style.</li></ol><p>MCP requires a Mapbox API key configured in <strong>Jeo → Settings</strong>. It is not used by any other feature.</p><h2 id="privacy-and-data" tabindex="-1">Privacy and data <a class="header-anchor" href="#privacy-and-data" aria-label="Permalink to &quot;Privacy and data&quot;">​</a></h2><p>Understanding what data is sent where:</p><table tabindex="0"><thead><tr><th>Data point</th><th>Sent to</th><th>Stored</th></tr></thead><tbody><tr><td>Post content (for analysis)</td><td>Your configured AI provider</td><td>No — used transiently</td></tr><tr><td>Geolocation queries</td><td>Your configured AI provider</td><td>No</td></tr><tr><td>Embeddings (knowledge base)</td><td>Your configured AI provider (during indexing)</td><td>Yes — stored locally in <code>wp-content/uploads/jeo-ai-store/</code></td></tr><tr><td>Conversation history</td><td>Not sent to AI provider after initial call</td><td>Yes — stored in WordPress post meta</td></tr><tr><td>User preferences (memory)</td><td>Not sent externally</td><td>Yes — stored in WordPress user meta</td></tr><tr><td>Mapbox styles (MCP only)</td><td>Mapbox MCP DevKit</td><td>Yes — stored as layer posts in WordPress</td></tr></tbody></table><p>If you use a <strong>local provider</strong> (Ollama), no data leaves your server at all.</p><h3 id="token-usage" tabindex="-1">Token usage <a class="header-anchor" href="#token-usage" aria-label="Permalink to &quot;Token usage&quot;">​</a></h3><p>JEO tracks AI token usage in <strong>Jeo → AI Debug Logs</strong>. Each log entry records the provider, model, input and output tokens, and the prompt and response. Use this to monitor costs and troubleshoot results.</p><h2 id="feature-—-concept-matrix" tabindex="-1">Feature — concept matrix <a class="header-anchor" href="#feature-—-concept-matrix" aria-label="Permalink to &quot;Feature — concept matrix&quot;">​</a></h2><p>A quick reference for which concepts apply to each feature:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Provider</th><th style="text-align:center;">RAG</th><th style="text-align:center;">Structured output</th><th style="text-align:center;">Tools</th><th style="text-align:center;">Conversation memory</th><th style="text-align:center;">MCP</th></tr></thead><tbody><tr><td><a href="/docs/ai-georeferencing/">AI Georeferencing</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td><a href="/docs/ai-bulk-geolocation/">AI Bulk Geolocation</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><a href="/docs/minimap/">Minimap</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td><a href="/docs/ai-context-assistant/">Context Assistant</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td>Minilayer</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong>Configure a provider</strong>: <a href="/docs/ai-settings/">AI Settings</a></li><li><strong>Index your content</strong>: Knowledge Base tab in <strong>Jeo → AI</strong></li><li><strong>Start using features</strong>: <ul><li><a href="/docs/ai-georeferencing/">AI Georeferencing</a> — auto-tag posts with locations</li><li><a href="/docs/minimap/">Minimap</a> — generate maps from text or post content</li><li><a href="/docs/ai-context-assistant/">Context Assistant</a> — get AI-powered editorial suggestions</li><li><a href="/docs/ai-bulk-geolocation/">AI Bulk Geolocation</a> — process many posts at once</li></ul></li></ul>',61)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
